<template>
  <section class="weekly-stats">
    <div class="stats-intro"><div><h2>组长完成情况</h2></div><button @click="load" :disabled="loading">刷新统计</button></div>
    <p v-if="loading" role="status">正在加载本周统计…</p>
    <div v-else-if="error" role="alert">{{error}} <button @click="load">重试</button></div>
    <template v-else-if="data">
      <details class="stats-help"><summary>状态说明</summary>      <div class="stats-legend"><span class="submitted">已提交</span><span class="abnormal">已填异常</span><span class="unfinished">明确未完成</span><span class="draft">草稿</span><span class="missing">未填报</span><span class="future">未到日期</span></div>
      <p class="stats-note">未填报不等于未做；异常不等于未履职。周一至周六中休息一天，R 不计漏报；未确认休息日时暂停评分。</p>
</details>
      <div class="mobile-roster"><nav class="roster-days" aria-label="统计日期"><button v-for="(date,i) in data.dates" :key="date" :class="{active:rosterDate===date}" @click="rosterDate=date;selectedDate=date;filter='all'">{{dayNames[i]}}<small>{{date.slice(5)}}</small></button></nav><button v-for="person in data.people" :key="person.userId" class="roster-person" :class="{active:String(person.userId)===String(personId)&&selectedDate===rosterDate}" @click="select(person,rosterDate)"><span><b>{{person.name}} · {{person.floor}}楼</b><small>{{person.calendar?.restDate?'休息 '+person.calendar.restDate.slice(5):'未设置休息日'}}</small></span><span v-if="rosterDay(person)?.rest">R 休息</span><span v-else-if="rosterDay(person)?.future">未到日期</span><span v-else><b>{{rosterDay(person)?.submitted||0}} / {{person.dailyDutyCount}} 项</b><small>未填 {{rosterDay(person)?.missing||0}} · 异常 {{rosterDay(person)?.abnormal||0}}</small></span><span>›</span></button><button class="matrix-toggle" @click="showMatrix=!showMatrix">{{showMatrix?'收起整周表格':'查看整周表格'}}</button></div>
      <div class="table-scroll" :class="{'show-mobile':showMatrix}" tabindex="0" aria-label="人员每日填报统计，可横向滚动">
        <table><caption>每日事项 · 点击单元格查看明细</caption><thead><tr><th scope="col">组长</th><th v-for="(date,i) in data.dates" :key="date" scope="col">{{dayNames[i]}}<small>{{date.slice(5)}}</small></th><th scope="col">本周已提交</th></tr></thead>
          <tbody><tr v-for="person in data.people" :key="person.userId"><th scope="row">{{person.name}}<small>{{person.floor}} 楼{{person.calendar?.confirmed?'':' · 未设休息日'}}</small></th><td v-for="day in person.days" :key="day.date"><button class="day-cell" :class="{selected:String(person.userId)===String(personId)&&day.date===selectedDate,future:day.future}" :aria-label="`${person.name} ${day.date} ${day.rest?'R 休息':day.future?'未到日期':`已提交${day.submitted}项，未填报${day.missing}项`}`" @click="select(person,day.date)"><template v-if="day.rest">R 休息</template><template v-else-if="day.future">未到日期</template><template v-else><b>{{day.submitted}} / {{person.dailyDutyCount}} 项</b><span>已提交</span><small v-if="day.unfinished" class="unfinished">未完成 {{day.unfinished}}</small><small v-if="day.abnormal" class="abnormal">异常 {{day.abnormal}}</small><small v-if="day.draft" class="draft">草稿 {{day.draft}}</small><small v-if="day.missing" class="missing">未填 {{day.missing}}</small></template></button></td><td><strong>{{person.totals.submitted}}</strong> 项次</td></tr></tbody>
        </table>
      </div>
      <p v-if="!data.people.length">本周暂无已配置的组长。</p>
      <section v-if="selectedPerson" class="day-detail"><button class="collapse-detail" @click="personId=''">收起明细</button>
        <div class="detail-heading"><div><h3>{{selectedPerson.name}} · {{selectedDate}} 事项明细</h3><p>查看组长填写的原始结果；点击“查看材料”可核对说明和照片。</p></div><label>显示事项<select v-model="filter"><option value="all">全部事项</option><option value="missing">未填报</option><option value="draft">草稿</option><option value="unfinished">明确未完成</option><option value="abnormal">已填异常</option></select></label></div>
        <div class="day-picker"><button v-for="(date,i) in data.dates" :key="date" :class="{active:date===selectedDate}" @click="selectedDate=date">{{dayNames[i]}}<small>{{date.slice(5)}}</small></button></div>
        <ul class="duty-status-list"><li v-for="item in filteredItems" :key="item.dutyId"><div><small>{{item.category}}</small><p>{{item.title}}</p></div><span class="status" :class="item.state">{{item.label}}</span><button v-if="item.recordId" @click="inspect(item)">查看材料</button></li></ul>
        <p v-if="!filteredItems.length">{{selectedPerson.days.find(d=>d.date===selectedDate)?.rest?'R 休息，当日免填。':'所选日期没有此类事项。'}}</p>
        <details class="other-cadence"><summary>本周任务 · {{selectedPerson.weekly.filter(i=>['submitted','abnormal','unfinished'].includes(i.state)).length}} / {{selectedPerson.weekly.length}} 项已提交</summary><ul class="duty-status-list"><li v-for="item in selectedPerson.weekly" :key="item.dutyId"><div><p>{{item.title}}</p><small>{{item.recordDate||'本周内完成一次'}}</small></div><span class="status" :class="item.state">{{item.label}}</span><button v-if="item.recordId" @click="inspect(item)">查看材料</button></li></ul></details>
        <details class="other-cadence"><summary>持续事项 · 按实际发生记录，不计每日未填</summary><ul class="duty-status-list"><li v-for="item in selectedPerson.continuous" :key="item.dutyId"><div><p>{{item.title}}</p><small>本周 {{item.submittedCount}} 条已提交 · {{item.recordDate?'最近记录 '+item.recordDate:'无强制每日填报要求'}}</small></div><span class="status" :class="item.state">{{item.label}}</span><button v-if="item.recordId" @click="inspect(item)">查看最近材料</button></li></ul></details>
      </section>
    </template>
  </section>
</template>

<script setup>
import {ref,computed,watch,onBeforeUnmount} from 'vue'
import {work} from '../api/work'
const props=defineProps({week:{type:String,required:true}}),emit=defineEmits(['inspect'])
const showMatrix=ref(false),rosterDate=ref('')
const data=ref(null),loading=ref(false),error=ref(''),personId=ref(''),selectedDate=ref(''),filter=ref('all')
const dayNames=['周一','周二','周三','周四','周五','周六','周日']
let sequence=0
async function load(){
  const seq=++sequence;loading.value=true;error.value='';data.value=null
  try{const result=await work.get('/week-statistics',{params:{week:props.week,workshop:'qu_making'}});if(seq!==sequence)return;data.value=result.data;personId.value='';selectedDate.value=result.data.dates.includes(result.data.today)?result.data.today:result.data.dates[0];filter.value='all';rosterDate.value=selectedDate.value}
  catch{if(seq===sequence)error.value='统计加载失败，请重试。未将加载失败显示为无人填报。'}
  finally{if(seq===sequence)loading.value=false}
}
const selectedPerson=computed(()=>data.value?.people.find(p=>String(p.userId)===personId.value))
const filteredItems=computed(()=>(selectedPerson.value?.days.find(d=>d.date===selectedDate.value)?.items||[]).filter(i=>filter.value==='all'||i.state===filter.value))
function rosterDay(person){return person.days.find(d=>d.date===rosterDate.value)}
function select(person,date){personId.value=String(person.userId);selectedDate.value=date;rosterDate.value=date;filter.value='all'}
function inspect(item){emit('inspect',{userId:selectedPerson.value.userId,recordId:item.recordId,dutyId:item.dutyId})}
watch(()=>props.week,load,{immediate:true});onBeforeUnmount(()=>sequence++)
</script>

<style scoped>
.weekly-stats{background:white;border:1px solid #e5e9ef;border-radius:14px;padding:20px;min-width:0}.stats-intro,.detail-heading{display:flex;justify-content:space-between;align-items:start;gap:16px}.weekly-stats h2,.weekly-stats h3{margin:0}.weekly-stats p{color:#637083;font-size:14px;line-height:1.6;margin:8px 0}.weekly-stats button,.weekly-stats select{font:inherit;padding:10px 12px;min-height:44px;background:white;border:1px solid #dce2ea;border-radius:8px;cursor:pointer}.weekly-stats button:focus-visible,.table-scroll:focus-visible{outline:2px solid #b51c31;outline-offset:2px}.stats-legend{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0}.stats-legend span,.status{padding:5px 9px;border-radius:6px;font-size:13px;white-space:nowrap}.submitted{color:#126c4f;background:#edf8f3}.abnormal{color:#915006;background:#fff5e4}.unfinished{color:#b22032;background:#fff0f2}.draft{color:#755512;background:#faf5e5}.missing{color:#657184;background:#f1f3f6}.future,.optional{color:#6b7583;background:#f6f7f9}.stats-note{font-size:13px!important}.table-scroll{max-width:100%;overflow:auto;border:1px solid #e5e9ef;border-radius:10px;margin-top:16px}.table-scroll table{border-collapse:separate;border-spacing:0;width:100%;min-width:990px;font-size:14px}.table-scroll caption{text-align:left;padding:14px;font-weight:600}.table-scroll th,.table-scroll td{padding:10px;border-bottom:1px solid #e5e9ef;text-align:center;vertical-align:top}.table-scroll thead th{background:#f6f8fb}.table-scroll th:first-child{position:sticky;left:0;z-index:1;min-width:100px;background:#f6f8fb}.table-scroll small{display:block;font-weight:400;margin-top:5px}.day-cell{width:100%;display:grid;gap:3px;min-width:92px;border-color:transparent!important;font-size:12px!important}.day-cell b{font-size:15px}.day-cell.selected{box-shadow:inset 0 0 0 2px #bf2438;background:#fff7f8}.day-detail{border-top:1px solid #e5e9ef;margin-top:24px;padding-top:24px}.detail-heading label{display:grid;gap:6px;min-width:130px}.day-picker{display:flex;gap:6px;overflow:auto;margin:16px 0}.day-picker button{flex:1;min-width:65px}.day-picker small{display:block;font-size:12px;margin-top:3px}.day-picker .active{background:#bf2438;color:white;border-color:#bf2438}.duty-status-list{list-style:none;padding:0;margin:0}.duty-status-list li{display:flex;align-items:center;gap:14px;padding:14px 0;border-bottom:1px solid #edf0f4}.duty-status-list li>div{flex:1;min-width:0}.duty-status-list small{color:#718096;font-size:12px}.duty-status-list p{margin:4px 0;color:#263548}.duty-status-list button{flex-shrink:0;font-size:13px}.other-cadence{padding-top:18px}.other-cadence summary{cursor:pointer;font-weight:600;line-height:1.6}
@media(max-width:700px){.weekly-stats{padding:14px}.stats-intro{display:block}.stats-intro>button{margin-top:8px}.detail-heading{display:block}.detail-heading label{margin-top:12px}.duty-status-list li{flex-wrap:wrap;gap:8px}.duty-status-list li>div{flex-basis:100%}.table-scroll th:first-child{min-width:76px}.day-detail{padding-top:18px}.day-picker button{padding:8px}.stats-legend{gap:6px}}
.stats-help{margin:10px 0;color:#67748a;font-size:13px}.stats-help summary{cursor:pointer}.mobile-roster{display:none}@media(max-width:700px){.mobile-roster{display:grid;gap:8px;margin-top:14px}.roster-days{display:flex;gap:4px;overflow:auto}.roster-days button{flex:1;padding:8px 5px;min-width:44px;font-size:12px}.roster-days small,.roster-person small{display:block;margin-top:4px;font-size:11px}.roster-days .active{background:#bd2035;color:white}.roster-person{display:flex;align-items:center;justify-content:space-between;gap:10px;text-align:left;font-size:13px!important}.roster-person.active{border-color:#bd2035;background:#fff8f8}.roster-person>span:nth-child(2){margin-left:auto;text-align:right}.roster-person small{color:#748194}.table-scroll{display:none}.table-scroll.show-mobile{display:block}.matrix-toggle{justify-self:end;font-size:12px!important}.stats-intro{display:flex;align-items:center}.stats-intro>button{margin:0;font-size:12px}.day-detail{margin-top:16px;padding-top:16px}}
.collapse-detail{float:right;font-size:12px!important;margin-bottom:10px}.detail-heading{clear:both}@media(max-width:700px){.day-picker{display:none}}
</style>
